function RhoCoeffs(N):
    r <- array of zeros, length N+1
    m <- 0
    while 2*m*(m+1) <= N:
        # reciprocal of partial denominator P_m = prod_{k=0}^{m} (1 + q^{2k+1} + q^{4k+2})
        inv <- [1, 0, 0, ..., 0]                 # the series 1
        for k in 0..m:
            poly  <- OneMinus(2k+1, N)           # 1 - q^{2k+1}
            gseries <- Geom(6k+3, N)             # sum_j q^{(6k+3)j}
            factorInv <- TruncMul(poly, gseries, N)   # = 1 / D_k mod q^{N+1}
            inv <- TruncMul(inv, factorInv, N)
        shift <- 2*m*(m+1)
        for n in 0..(N - shift):
            r[n + shift] <- r[n + shift] + inv[n]
        m <- m + 1
    return r

function TruncMul(a, b, N):
    c <- array of zeros, length N+1
    for i in 0..N with a[i] != 0:
        for j in 0..(N - i):
            c[i + j] <- c[i + j] + a[i] * b[j]
    return c
